    # can q (4 distinct digits) be split into two pairs with equal products?
    q = list(q)
    for a,b,c,d in [(q[0],q[1],q[2],q[3]),(q[0],q[2],q[1],q[3]),(q[0],q[3],q[1],q[2])]:
        if a*b == c*d:
