import itertools

faces = list(range(6))
opp = {0:3, 3:0, 1:4, 4:1, 2:5, 5:2}
adj = {f: [g for g in faces if g != f and g != opp[f]] for f in faces}

# count directed Hamiltonian cycles starting at face 0 (each directed cycle counted once by its start at 0)
count = 0
for perm in itertools.permutations([1,2,3,4,5]):
    seq = (0,) + perm
    ok = all(seq[i+1] in adj[seq[i]] for i in range(5)) and seq[0] in adj[seq[5]]
    if ok:
        count += 1
print("directed cycles (undirected*2):", count)

# brute force over all arrow assignments
total = 0
for choices in itertools.product(*[adj[f] for f in faces]):
    f = {faces[i]: choices[i] for i in range(6)}
    # check single 6-cycle
    seen = set()
    x = 0
    for _ in range(6):
        x = f[x]
        seen.add(x)
    if len(seen) == 6:
        total += 1
print("arrow drawings:", total)
