def count_valid_selections(n):
    squares = [(i, j) for i in range(n) for j in range(n)]
    k = 2 * n - 2
    count = 0
    for combo in itertools.combinations(squares, k):
        diffs = set()
        sums = set()
        valid = True
        for (i, j) in combo:
            d = i - j
            s = i + j
            if d in diffs or s in sums:
                valid = False
                break
            diffs.add(d)
            sums.add(s)
        if valid:
            count += 1
    return count

for n in range(2, 7):
    print(f"n={n}: {count_valid_selections(n)}")"}
